python -I -c "
import pdfplumber,glob,os
for f in sorted(glob.glob('package/*')):
    try:
        with pdfplumber.open(f) as p:
            n=len(p.pages); t=sum(len((pg.extract_text() or '')) for pg in p.pages[:5])
            sizes=set((round(pg.width),round(pg.height)) for pg in p.pages)
            print(n, t, list(sizes)[:6], os.path.getsize(f)//1024,'KB', f)
    except Exception as e: print('ERR',f,e)
"

